ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"tableNumber": vars.getVariablesResponse.variables[0].'Tabla_Asignada'
}

ee:message.ee:set-payload:
%dw 2.0 output application/json var scoreToCheck = vars.getIdentityResponse.identity[0].'score_movil'.Valor default 0 var rangos = vars.getGeoreferenceResponse.georeference[0].Rangos
var matchedRange = rangos filter (rango) -> do { var parts = rango.Codigo splitBy "_" var low = parts[0] as Number var high = parts[1] as Number --- scoreToCheck >= low and scoreToCheck <= high }
var lteScore = (matchedRange[0].Detalle map ((item, index) -> { "Status Score": item.Nombre, "Valor Maximo": item.Valor as Number, "Oferta": vars.initialPayload.model.technology, "Segmento": vars.initialPayload.model.segment }))[0] --- { code: "200", message: "cliente validado exitosamente", result: lteScore }

%dw 2.0 var numberToCheck = vars.getIdentityResponse.identity[0].'score_fija'.Valor default 0 var estrato = 1 // will be replaced once we get the logic var rangos = vars.getGeoreferenceResponse.georeference[0].Rangos
var matchedRange = rangos filter (rango) -> do { var parts = rango.Codigo splitBy "_" var low = parts[0] as Number var high = parts[1] as Number --- numberToCheck >= low and numberToCheck <= high }
var matchedDetalle = (matchedRange[0].Detalle default []) filter (d) -> d.Nombre == ("ESTRATO " ++ (estrato as String))
var fixedScore = (matchedDetalle map ((item, index) -> { "Status Score": item.Nombre, "Valor Maximo": item.Valor as Number, "Oferta": vars.initialPayload.model.technology, "Segmento": vars.initialPayload.model.segment }))[0]
output application/json --- { code: "200", message: "cliente validado exitosamente", result: fixedScore }

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"tableNumber": vars.getVariablesResponse.variables[0].'Tabla_Asignada'
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
var score = if ( vars.initialPayload.model == 1 ) {
	"score_movil": {
		"Valor": vars.postLisimScoreResponse.score as String,
		"Fecha": now() as Date
	}
} else {
	"score_fija": {
		"Valor": vars.postLisimScoreResponse.score as String,
		"Fecha": now() as Date
	}
}
---
{
	"estado": "VIGENTE",
	"causal": "VALIDACION OBTENIDA EXITOSAMENTE"
} ++ score

%dw 2.0 output application/json var scoreToCheck = vars.postLisimScoreResponse.score var rangos = vars.getGeoreferenceResponse.georeference[0].Rangos
var matchedRange = rangos filter (rango) -> do { var parts = rango.Codigo splitBy "_" var low = parts[0] as Number var high = parts[1] as Number --- scoreToCheck >= low and scoreToCheck <= high }
var lteScore = (matchedRange[0].Detalle map ((item, index) -> { "Status Score": item.Nombre, "Valor Maximo": item.Valor as Number, "Oferta": vars.osValidationDetail.technology, "Segmento": vars.osValidationDetail.segment }))[0] --- { code: "200", message: "cliente validado exitosamente", result: lteScore }

%dw 2.0 var numberToCheck = vars.postLisimScoreResponse.score var estrato = vars.initialPayload.stratum default 0 var rangos = vars.getGeoreferenceResponse.georeference[0].Rangos
var matchedRange = rangos filter (rango) -> do { var parts = rango.Codigo splitBy "_" var low = parts[0] as Number var high = parts[1] as Number --- numberToCheck >= low and numberToCheck <= high }
var matchedDetalle = (matchedRange[0].Detalle default []) filter (d) -> d.Nombre == ("ESTRATO " ++ (estrato as String))
var fixedScore = (matchedDetalle map ((item, index) -> { "Status Score": item.Nombre, "Valor Maximo": item.Valor as Number, "Oferta": vars.osValidationDetail.technology, "Segmento": vars.osValidationDetail.segment }))[0]
output application/json --- { code: "200", message: "cliente validado exitosamente", result: fixedScore }

%dw 2.0
output application/json

var isStringResult = vars.postLisimOtpResponse.result is String
var isObjectResult = vars.postLisimOtpResponse.result is Object
var hasMessageServer =
  isObjectResult and vars.postLisimOtpResponse.result.messageServer != null

---
{
  code: "200",
  message:
    if (isStringResult)
      vars.postLisimOtpResponse.result
    else if (hasMessageServer)
      vars.postLisimOtpResponse.result.messageServer
    else
      "envio exitoso"
}
++
(
  if (isStringResult)
    { result: vars.postLisimOtpResponse.result }
  else if (isObjectResult and not hasMessageServer)
    { result: vars.postLisimOtpResponse.result }
  else
    {}
)

%dw 2.0 output application/json
var hasMessageServer = payload.messageServer != null
--- { code: "200", message: if (hasMessageServer) payload.messageServer else "Questionario generado exitosamente", questions: if (hasMessageServer) [] else payload default [] }

%dw 2.0
output application/json

var hasMessageServer =
  vars.postLisimQuestionnarieResponse.result is Object and vars.postLisimQuestionnarieResponse.result.messageServer != null

---
{
  code: "200",
  message:
    if (hasMessageServer)
      vars.postLisimQuestionnarieResponse.result.messageServer
    else
      vars.postLisimQuestionnarieResponse.result
}
++
(
  if (not hasMessageServer)
    { result: vars.postLisimQuestionnarieResponse.result }
  else
    {}
)

%dw 2.0
output application/json
---
{
	"fields": [],
	"filters": [{
		"field": "TipoIdentificacion",
		"value": attributes.queryParams.document_id_type
	},
    {
		"field": "Identificacion",
		"value": attributes.queryParams.document_id
	},
    {
		"field": "EstadoRegistro",
		"value": "Activo"
	}],
	"limit": 10
}

